package org.apache.commons.lang3.math;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.lang3.StringUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class NumberUtils_createNumber_TriageGen5Test {

    @Test
    public void testCreateNumber_Null() {
        assertNull(NumberUtils.createNumber(null));
    }

    @Test(expected = NumberFormatException.class)
    public void testCreateNumber_Blank() {
        NumberUtils.createNumber("   ");
    }

    @Test
    public void testCreateNumber_DoubleDash() {
        assertNull(NumberUtils.createNumber("--123"));
    }

    @Test
    public void testCreateNumber_Hex() {
        // Assuming createInteger handles hex
        Number result = NumberUtils.createNumber("0x12");
        assertTrue(result instanceof Integer);
        assertEquals(18, result.intValue());
    }

    @Test
    public void testCreateNumber_HexNegative() {
        Number result = NumberUtils.createNumber("-0x12");
        assertTrue(result instanceof Integer);
        assertEquals(-18, result.intValue());
    }

    @Test
    public void testCreateNumber_Integer() {
        Number result = NumberUtils.createNumber("123");
        assertTrue(result instanceof Integer);
        assertEquals(123, result.intValue());
    }

    @Test
    public void testCreateNumber_Long() {
        // Using a value that fits in Long but not necessarily Integer depending on createInteger impl
        Number result = NumberUtils.createNumber("3000000000");
        assertTrue(result instanceof Long || result instanceof BigInteger);
    }

    @Test
    public void testCreateNumber_BigInteger() {
        String bigVal = "999999999999999999999999999999";
        Number result = NumberUtils.createNumber(bigVal);
        assertTrue(result instanceof BigInteger);
        assertEquals(new BigInteger(bigVal), result);
    }

    @Test
    public void testCreateNumber_FloatSuffix() {
        Number result = NumberUtils.createNumber("123.45f");
        assertTrue(result instanceof Float);
        assertEquals(123.45F, ((Float) result).floatValue(), 0.001);
    }

    @Test
    public void testCreateNumber_DoubleSuffix() {
        Number result = NumberUtils.createNumber("123.45d");
        assertTrue(result instanceof Double);
        assertEquals(123.45D, ((Double) result).doubleValue(), 0.001);
    }

    @Test
    public void testCreateNumber_LongSuffix() {
        Number result = NumberUtils.createNumber("123L");
        assertTrue(result instanceof Long);
        assertEquals(123L, result.longValue());
    }

    @Test
    public void testCreateNumber_BigIntegerSuffix() {
        // A very large number with L suffix to trigger BigInteger
        String bigVal = "999999999999999999999999999999L";
        Number result = NumberUtils.createNumber(bigVal);
        assertTrue(result instanceof BigInteger);
    }

    @Test
    public void testCreateNumber_DecimalAndExp() {
        Number result = NumberUtils.createNumber("1.23e2");
        // 1.23 * 10^2 = 123.0
        assertTrue(result instanceof Double || result instanceof Float || result instanceof BigDecimal);
        assertEquals(123.0, ((Number)result).doubleValue(), 0.001);
    }

    @Test
    public void testCreateNumber_DecimalNoExp() {
        Number result = NumberUtils.createNumber("123.456");
        assertTrue(result instanceof Double || result instanceof Float || result instanceof BigDecimal);
        assertEquals(123.456, result.doubleValue(), 0.001);
    }

    @Test
    public void testCreateNumber_ExpNoDecimal() {
        Number result = NumberUtils.createNumber("1e2");
        assertEquals(100.0, result.doubleValue(), 0.001);
    }

    @Test
    public void testCreateNumber_InvalidExpPos() {
        // expPos < decPos scenario
        // if 'e' comes before '.' in a way that logic fails
        // The code says: if (expPos < decPos) throw exception
        // Note: expPos is calculated as str.indexOf('e') + str.indexOf('E') + 1
        // This calculation is actually buggy in the source (it sums indices), 
        // but we must test the branch.
        // If 'e' is at index 1 and '.' is at index 5, expPos = 1 + 0 + 1 = 2. 2 < 5.
        assertThrows(NumberFormatException.class, () -> NumberUtils.createNumber("1e.5"));
    }

    @Test
    public void testCreateNumber_InvalidSuffix() {
        assertThrows(NumberFormatException.class, () -> NumberUtils.createNumber("123.45z"));
    }

    @Test
    public void testCreateNumber_FloatPrecisionFallback() {
        // Case where Float is too imprecise or results in 0.0 but not all zeros
        // "0.000000000000000000000000000000000000001"
        String tiny = "0.000000000000000000000000000000000000001";
        Number result = NumberUtils.createNumber(tiny);
        // Should fall through to Double or BigDecimal
        assertFalse(result instanceof Float);
    }

    @Test
    public void testCreateNumber_AllZeros() {
        Number result = NumberUtils.createNumber("0.000e0");
        assertEquals(0.0, result.doubleValue(), 0.0);
    }

    @Test
    public void testCreateNumber_NegativeLongSuffix() {
        Number result = NumberUtils.createNumber("-123L");
        assertEquals(-123L, result.longValue());
    }

    @Test
    public void testCreateNumber_BigDecimalFallback() {
        // Force fallback to BigDecimal by providing a very long decimal
        String longDec = "1.123456789012345678901234567890";
        Number result = NumberUtils.createNumber(longDec);
        assertTrue(result instanceof BigDecimal);
    }

    @Test
    public void testCreateNumber_DecimalWithExpSuffix() {
        // Test the logic for 'e' inside the suffix detection
        // e.g., "1.23e2f"
        Number result = NumberUtils.createNumber("1.23e2f");
        assertTrue(result instanceof Float);
        assertEquals(123.0F, ((Float) result).floatValue(), 0.001);
    }

    @Test
    public void testCreateNumber_InvalidFormat() {
        assertThrows(NumberFormatException.class, () -> NumberUtils.createNumber("abc"));
    }

    // Helper to handle JUnit 4 style expected exceptions in a cleaner way for complex tests
    private <T> void assertThrows(Class<T> expectedType, ThrowingRunnable runnable) {
        try {
            runnable.run();
            fail("Expected " + expectedType.getName() + " but no exception was thrown");
        } catch (Exception e) {
            if (!expectedType.isInstance(e)) {
                fail("Expected " + expectedType.getName() + " but caught " + e.getClass().getName());
            }
        }
    }

    @FunctionalInterface
    interface ThrowingRunnable {
        void run() throws Exception;
    }
}
